cd /Users/bymyway/github_repos/northern411 && python3 << 'PY'
import sys, re
path = "index.html"
with open(path, "r", encoding="utf-8") as f:
    s = f.read()

# 改動 1：第二場次 → 第三場次
old1 = '<span class="session-divider-badge">第二場次</span>'
new1 = '<span class="session-divider-badge">第三場次</span>'
if s.count(old1) != 1:
    print(f"❌ 第二場次找到 {s.count(old1)} 次,中止")
    sys.exit(1)
s = s.replace(old1, new1)

# 改動 2：在 <body> 開始後插入 fixed top navbar（含 CSS + nav）
nav_block = '''
<style>
  /* 🆕 固定頂部導覽列（教練 2026-06-17 親定 7 個按鈕） */
  .top-nav-bar{position:fixed;top:0;left:0;right:0;z-index:1000;background:rgba(18,34,56,.95);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);border-bottom:1px solid rgba(255,255,255,.1);padding:10px 0;box-shadow:0 2px 12px rgba(0,0,0,.2)}
  .top-nav-bar .nav-inner{max-width:1200px;margin:0 auto;display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:center;padding:0 16px}
  .top-nav-bar a{color:#fff;text-decoration:none;padding:7px 14px;border-radius:6px;font-size:14px;font-weight:700;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);transition:all .2s;white-space:nowrap}
  .top-nav-bar a:hover{background:#c9a86a;color:#122238;border-color:#c9a86a}
  .top-nav-bar a.primary{background:#c9a86a;color:#122238;border-color:#c9a86a}
  .top-nav-bar a.primary:hover{background:#fff;color:#122238;border-color:#fff}
  body{padding-top:60px}
  @media (max-width:880px){
    .top-nav-bar .nav-inner{overflow-x:auto;justify-content:flex-start;flex-wrap:nowrap;padding:0 12px;-webkit-overflow-scrolling:touch}
    .top-nav-bar .nav-inner::-webkit-scrollbar{display:none}
    .top-nav-bar a{font-size:13px;padding:6px 12px;flex:0 0 auto}
    body{padding-top:54px}
  }
</style>
<nav class="top-nav-bar" aria-label="主要導覽">
  <div class="nav-inner">
    <a class="primary" href="#signup-626">報名參與本論壇</a>
    <a href="#theme-626">論壇主題</a>
    <a href="#speakers-626">演講者陣容</a>
    <a href="#schedule-626">論壇議程</a>
    <a href="#orgs-626">相關單位</a>
    <a href="#sponsor-626">廠商贊助</a>
    <a href="#session-411">歷屆回顧</a>
  </div>
</nav>
'''
# 插入在 <body> 開標籤之後
new_s, n = re.subn(r'(<body[^>]*>)', r'\1' + nav_block, s, count=1)
if n != 1:
    print(f"❌ <body> tag 找到 {n} 個,中止")
    sys.exit(1)

with open(path, "w", encoding="utf-8") as f:
    f.write(new_s)

print("✅ 兩處改動完成")
print("- 第三場次:", new_s.count("第三場次"), "次")
print("- top-nav-bar:", new_s.count("top-nav-bar"), "次")
print("- 7 個 nav 按鈕:", sum(new_s.count(x) for x in ["#signup-626", "#theme-626", "#speakers-626", "#schedule-626", "#orgs-626", "#sponsor-626", "#session-411"]), "個 anchor 引用")
